import json, urllib.request, ssl, time
ctx = ssl.create_default_context()
BASE = 'https://api.ivxholding.com'
token = open('/tmp/owner_token.txt').read().strip()

def call(url, method='GET', data=None, timeout=30):
    h = {'Content-Type':'application/json','Authorization':f'Bearer {token}'}
    req = urllib.request.Request(url, data=json.dumps(data).encode() if data else None, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        b = e.read().decode()[:500]
        try: b = json.loads(b)
        except: pass
        return e.code, b
    except Exception as ex:
        return 0, str(ex)[:300]

# First get fresh token (old one might be expired)
st, b = call(f'{BASE}/api/ivx/owner-passwordless-login', 'POST', {'email':'iperez4242@gmail.com','emergency':'ivx_emergency_recovery'}, timeout=20)
if st == 200 and b.get('accessToken'):
    token = b['accessToken']
    with open('/tmp/owner_token.txt','w') as f: f.write(token)
    print(f'Fresh token: {token[:15]}...{token[-4:]}')
else:
    print(f'Token refresh: HTTP {st}, using existing token')

# Trigger Render deploy
print()
print('=== TRIGGERING RENDER DEPLOY ===')
st, b = call(f'{BASE}/api/ivx/developer-deploy/action', 'POST', {
    'action': 'render_trigger_deploy',
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_RENDER_DEPLOY',
    'input': {}
})
print(f'HTTP {st}')
print(json.dumps(b, indent=2)[:800])
" 2>&1

