import json, urllib.request, ssl, time
ctx = ssl.create_default_context()
BASE = 'https://api.ivxholding.com'

def fetch(url, timeout=15):
    req = urllib.request.Request(url)
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status, json.loads(r.read().decode())
    except Exception as ex:
        return 0, str(ex)[:200]

# Get fresh owner token
def post(url, data, timeout=20):
    h = {'Content-Type':'application/json'}
    req = urllib.request.Request(url, data=json.dumps(data).encode(), headers=h, method='POST')
    with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
        return json.loads(r.read().decode())

body = post(f'{BASE}/api/ivx/owner-passwordless-login', {'email':'iperez4242@gmail.com','emergency':'ivx_emergency_recovery'})
token = body.get('accessToken','')
with open('/tmp/owner_token.txt','w') as f: f.write(token)

def auth_call(url, method='GET', data=None, timeout=30):
    h = {'Content-Type':'application/json','Authorization':f'Bearer {token}'}
    req = urllib.request.Request(url, data=json.dumps(data).encode() if data else None, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        b = e.read().decode()[:300]
        try: b = json.loads(b)
        except: pass
        return e.code, b
    except Exception as ex:
        return 0, str(ex)[:200]

# Poll for deploy completion
gh_sha = None
for i in range(20):
    time.sleep(15)
    st, h = fetch(f'{BASE}/health')
    st2, gh = fetch('https://api.github.com/repos/ibb142/ivx-holdings-platform/commits/main')
    gh_sha = gh.get('sha','?')
    api_sha = h.get('commit','?')
    boot = h.get('bootTime','?')
    match = gh_sha == api_sha
    print(f'Poll {i+1}/20: GitHub={gh_sha[:12]} Render={api_sha[:12]} boot={boot} match={match}')
    if match:
        print('SHA PARITY ACHIEVED!')
        break
else:
    print('Deploy still in progress after 5 minutes — checking Render deploy status...')
    st, b = auth_call(f'{BASE}/api/ivx/developer-deploy/action', 'POST', {
        'action': 'render_get_deploy_status',
        'confirm': True,
        'confirmText': 'CONFIRM_IVX_RENDER_DEPLOY',
        'input': {}
    })
    print(f'Render deploy status: HTTP {st}')
    print(json.dumps(b, indent=2)[:1000] if isinstance(b,dict) else str(b)[:500])
" 2>&1

