   315|  }
   316|  if (!job.status) {
   317|    missing.push('status');
   318|  }
   319|  if (!job.stage) {
   320|    missing.push('currentStage');
   321|  }
   322|
   323|  if (job.status && !allowedStatuses.includes(job.status)) {
   324|    return {
   325|      valid: false,
   326|      state: 'UNVERIFIED',
   327|      reason: `Invalid structured status: ${job.status}`,
   328|      contradictions,
   329|      missing,
   330|    };
   331|  }
