   336|    if (job.progress === undefined || job.progress === null) missing.push('progress');
   337|    if (!job.currentAction) missing.push('currentAction');
   338|  }
   339|
   340|  if (job.status === 'BLOCKED') {
   341|    if (!job.blockedReason && !job.error) missing.push('exact blocker or error');
   342|    if (!job.completedSteps || job.completedSteps.length === 0) missing.push('completed steps');
   343|  }
   344|
   345|  if (job.status === 'COMPLETED') {
   346|    if (!job.tests || !job.tests.run) missing.push('tests');
   347|    if (job.filesChanged === undefined || job.filesChanged.length === 0) missing.push('filesChanged');
   348|  }
   349|
   350|  // Structural contradiction: a completed job cannot have a blocking reason.
   351|  if (job.status === 'COMPLETED' && job.blockedReason) {
   352|    contradictions.push('COMPLETED + blockedReason');
