   354|      valid: false,
   355|      state: 'UNVERIFIED',
   356|      reason: 'COMPLETED job cannot carry a blockedReason',
   357|      contradictions,
   358|      missing,
   359|    };
   360|  }
   361|
   362|  // Missing required fields makes the structured record invalid.
   363|  if (missing.length > 0) {
   364|    return {
   365|      valid: false,
   366|      state: 'UNVERIFIED',
   367|      reason: `Structured job record incomplete: missing ${missing.join(', ')}`,
   368|      contradictions,
   369|      missing,
   370|    };
   371|  }
   372|
   373|  const stateMap: Record<IVXIAJobStatusValue, IVXIAState> = {
   374|    QUEUED: 'RUNNING',
   375|    CLAIMED: 'RUNNING',
   376|    RUNNING: 'RUNNING',
   377|    TESTING: 'RUNNING',
   378|    WAITING_OWNER: 'WAITING_OWNER',
   379|    BLOCKED: 'BLOCKED',
   380|    FAILED: 'FAILED',
   381|    COMPLETED: 'VERIFIED',
   382|    CANCELLED: 'BLOCKED',
   383|  };
   384|
   385|  return {
   386|    valid: true,
   387|    state: stateMap[job.status],
   388|    reason: null,
   389|    contradictions,
   390|    missing,
   391|  };
