   498|  contradictions: string[];
   499|  bannedPromises: string[];
   500|  missingEvidence: string[];
   501|  reason: string | null;
   502|} {
   503|  // ── Structured job record is the single source of truth. ─────────────────
   504|  if (structured) {
   505|    const validation = validateStructuredJobEvidence(structured);
   506|    if (!validation.valid) {
   507|      return {
   508|        state: validation.state,
   509|        contradictions: validation.contradictions,
   510|        bannedPromises: [],
   511|        missingEvidence: validation.missing,
   512|        reason: validation.reason,
   513|      };
   514|    }
   515|    return {
   516|      state: validation.state,
   517|      contradictions: [],
   518|      bannedPromises: [],
   519|      missingEvidence: validation.missing,
   520|      reason: null,
   521|    };
   522|  }
   523|
   524|  // ── Fallback: text-based scanning (only when no structured job provided). ──
   525|  // Strip quoted / code-fenced text so words like "completed" or "blocked"
   526|  // inside logs, quoted user messages, or error descriptions do not trigger
   527|  // false positives. NOTE: text-based contradiction detection has been removed;
   528|  // the only valid contradiction is an inconsistent structured job record.
