   536|
   537|  // No text-based contradiction detection. The only contradictions are from
   538|  // structured validation (COMPLETED + blockedReason, etc.) handled above.
   539|  const contradictions: string[] = [];
   540|
   541|  if (successAssertions.length > 0 && missingEvidence.length > 0) {
   542|    return {
   543|      state: 'BLOCKED',
   544|      contradictions,
   545|      bannedPromises,
   546|      missingEvidence,
   547|      reason: `Success claim (${successAssertions.join(', ')}) without required evidence: ${missingEvidence.join(', ')}.`,
   548|    };
   549|  }
   550|
   551|  if (successAssertions.length > 0 && missingEvidence.length === 0) {
   552|    return { state: 'VERIFIED', contradictions, bannedPromises, missingEvidence, reason: null };
   553|  }
   554|
   555|  if (failureAssertions.length > 0) {
   556|    const lowerFailure = failureAssertions.map((f) => lower(f));
   557|    const isWaiting = lowerFailure.some((f) => f.includes('waiting') || f.includes('awaiting') || f.includes('approval'));
   558|    const isFailed = lowerFailure.some((f) => f.includes('failed') || f.includes('could not') || f.includes('unable'));
