   561|    return { state, contradictions, bannedPromises, missingEvidence, reason: null };
   562|  }
   563|
   564|  if (bannedPromises.length > 0) {
   565|    return {
   566|      state: 'BLOCKED',
   567|      contradictions,
   568|      bannedPromises,
   569|      missingEvidence,
   570|      reason: `Generic promise without evidence: ${bannedPromises.join(', ')}. Inspection / execution has not actually started (no task id or evidence attached).`,
   571|    };
   572|  }
   573|
   574|  return { state: 'READY', contradictions, bannedPromises, missingEvidence, reason: null };
   575|}
