   648|/**
   649| * Apply the IVX IA Reliability Gate to a chat answer.
   650| *
   651| * When a structured job record is provided, the gate derives status from the
   652| * job and returns a clean structured answer. When no structured job is
   653| * provided, the gate falls back to text scanning for contradictions, banned
   654| * promises, and missing evidence.
   655| */
   656|export function applyIVXIAReliabilityGate(
   657|  input: IVXIAReliabilityGateInput,
   658|): IVXIAReliabilityGateResult {
   659|  const answer = trimmed(input.answer);
   660|  const resolution = resolveSingleState(answer, input.evidence, input.structured ?? null);
