   663|  // owner-mandated structured format. This ensures one terminal response per
   664|  // task and removes narrative contradictions.
   665|  if (input.structured && resolution.reason === null) {
   666|    const structuredAnswer = buildStructuredStatusAnswer(input.structured);
   667|    return {
   668|      answer: structuredAnswer,
   669|      gated: structuredAnswer !== answer,
   670|      state: resolution.state,
   671|      contradictions: [],
   672|      bannedPromises: [],
   673|      missingEvidence: [],
   674|      reason: null,
   675|    };
   676|  }
   677|
   678|  // If structured evidence is provided but invalid, build a blocked answer that
   679|  // names the exact validation failure (missing taskId, COMPLETED + blockedReason, etc.).
   680|  if (input.structured && resolution.reason !== null) {
   681|    const blockedAnswer = buildReliabilityBlockedAnswer({
   682|      state: resolution.state,
   683|      reason: resolution.reason,
   684|      missingEvidence: resolution.missingEvidence,
   685|      contradictions: resolution.contradictions,
   686|      bannedPromises: [],
   687|    });
   688|    return {
   689|      answer: blockedAnswer,
   690|      gated: true,
   691|      state: resolution.state,
   692|      contradictions: resolution.contradictions,
   693|      bannedPromises: [],
   694|      missingEvidence: resolution.missingEvidence,
   695|      reason: resolution.reason,
   696|    };
   697|  }
   698|
   699|  // Pass-through states: READY (no claim), VERIFIED (claim + full evidence),
   700|  // and pure failure/waiting states that have NO contradictions, banned promises,
   701|  // or missing evidence (e.g. an already-BLOCKED senior-developer answer).
   702|  // We only intervene when there is an actual reliability violation to fix.
   703|  const hasViolation =
   704|    resolution.contradictions.length > 0
   705|    || resolution.bannedPromises.length > 0
   706|    || resolution.missingEvidence.length > 0;
   707|
   708|  if (!hasViolation) {
   709|    return {
   710|      answer,
   711|      gated: false,
   712|      state: resolution.state,
   713|      contradictions: resolution.contradictions,
