import json, urllib.request, ssl, time

ctx = ssl.create_default_context()
BASE = 'https://api.ivxholding.com'

def fetch(url, timeout=10):
    req = urllib.request.Request(url)
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return json.loads(r.read().decode())
    except: return {}

def post(url, data, timeout=30, token=None):
    h = {'Content-Type':'application/json'}
    if token: h['Authorization'] = f'Bearer {token}'
    body = json.dumps(data).encode('utf-8')
    req = urllib.request.Request(url, data=body, headers=h, method='POST')
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        b = e.read().decode()[:500]
        try: b = json.loads(b)
        except: pass
        return e.code, b
    except Exception as ex:
        return 0, str(ex)[:300]

# Fresh owner token
st, b = post(f'{BASE}/api/ivx/owner-passwordless-login', {'email':'iperez4242@gmail.com','emergency':'ivx_emergency_recovery'})
token = b.get('accessToken','')
with open('/tmp/owner_token.txt','w') as f: f.write(token)

# Check deploy status
st2, b2 = post(f'{BASE}/api/ivx/developer-deploy/action', {
    'action': 'developer_deploy_status',
    'confirm': True,
    'confirmText': 'CONFIRM_IVX_DEVELOPER_DEPLOY',
    'input': {}
}, token=token)

if isinstance(b2, dict) and b2.get('result'):
    r = b2['result']
    gh_head = r.get('githubHead', {})
    render = r.get('renderDeploy', {})
    prod = r.get('productionHealth', {})
    print(f'GitHub HEAD:     {str(gh_head.get("headSha","?"))[:12]}')
    print(f'Render deploy:   status={render.get("status")} deployId={render.get("deployId","?")}')
    print(f'Prod health:     commit={str(prod.get("commit","?"))[:12]} status={prod.get("status")}')
    print(f'Prod boot:        {prod.get("bootTime","?")}')

    # Check if there's an active deploy
    if render.get('status') in ['build_in_progress', 'accepted', None]:
        print(f'\nDeploy in progress. Polling...')
        gh_sha = gh_head.get('headSha','?')
        for i in range(10):
            time.sleep(5)
            h = fetch(f'{BASE}/health')
            api_sha = h.get('commit','?')
            boot = h.get('bootTime','?')
            match = gh_sha == api_sha
            print(f'{(i+1)*5:3d}s: Render={api_sha[:12]} boot={boot} match={match}')
            if match and gh_sha != '?':
